// 入力: { approvers: string|string[], subject, body, timeout_days? }
// 出力: { approved, responder, responded_at, timed_out }
//
// 承認リンク方式(チャネル非依存)。本文に承認/却下リンクを埋め込んで notify で送る。
// リンクをどのチャネルで送ってもクリックで実行が再開されるため、
// チャネルが決まっていなくても承認フローが成立する。
// 設計: docs/design/04-notification-abstraction.md

const inp = $input.first()?.json ?? {};

const list = Array.isArray(inp.approvers) ? inp.approvers : (inp.approvers ? [inp.approvers] : []);
const approvers = list.filter((a) => typeof a === 'string' && /^[^@\s]+@[^@\s]+$/.test(a));
if (approvers.length === 0) {
  throw new Error(`request-approval: 有効な承認者がいません: ${JSON.stringify(inp.approvers)}`);
}
if (!inp.subject) throw new Error('request-approval: subject は必須です');

const timeoutDays = Number(inp.timeout_days ?? 3);

// 実行を再開する URL。クエリで承認/却下を区別する。
const resume = $execution.resumeUrl;
if (!resume) throw new Error('request-approval: resumeUrl を取得できません');

// n8n の resumeUrl は署名付きで既にクエリを含む(?signature=...)。
// そのまま '?' で連結すると URL が壊れるため区切り文字を判定する。
const sep = resume.includes('?') ? '&' : '?';
const approveUrl = `${resume}${sep}decision=approve`;
const rejectUrl = `${resume}${sep}decision=reject`;

const body = [
  String(inp.body ?? ''),
  '',
  '───────────────',
  `承認する: ${approveUrl}`,
  `却下する: ${rejectUrl}`,
  '',
  `※ ${timeoutDays} 日以内に応答がない場合は失効します。`,
].join('\n');

return [{ json: {
  approvers,
  to: approvers,          // notify の入力インターフェースに合わせる
  subject: inp.subject,
  body,
  timeoutDays,
  requestedAt: new Date().toISOString(),
}}];

// 再開時のクエリから承認/却下を判定する。
// 期限切れで再開した場合は decision が無いので timed_out として返す。
const ctx = $('承認依頼を組み立てる').first().json;
const resumed = $input.first()?.json ?? {};

const decision = resumed.query?.decision ?? resumed.decision ?? null;

if (decision === null) {
  return [{ json: {
    approved: false,
    responder: null,
    responded_at: null,
    timed_out: true,
    requested_at: ctx.requestedAt,
  }}];
}

return [{ json: {
  approved: decision === 'approve',
  // 誰が押したかはリンク方式では特定できない。宛先が承認者本人である前提。
  // 本人性が必要になったら署名付きトークンを付与して検証する(04 参照)。
  responder: ctx.approvers.join(','),
  responded_at: new Date().toISOString(),
  timed_out: false,
  requested_at: ctx.requestedAt,
}}];
